import os,pathlib,json,subprocess,re,xml.etree.ElementTree as ET,pwd
root=pathlib.Path('/srv/projects/jellyfin-server')
svc='jellyfin-pink.service'
def run(a,t=8):
 try:return subprocess.run(a,capture_output=True,text=True,timeout=t)
 except (OSError,subprocess.TimeoutExpired):return None
def prop(k):
 x=run(['systemctl','show',svc,'--property='+k,'--value'])
 return x.stdout.strip() if x and x.returncode==0 else None
user=prop('User')
r={'scope':'Jellyfin native encoder and service restrictions; no provider media or secrets','active':prop('ActiveState'),'service_user':user,'private_network':prop('PrivateNetwork'),'restrict_address_families':prop('RestrictAddressFamilies'),'ip_address_deny':prop('IPAddressDeny'),'ip_address_allow':prop('IPAddressAllow'),'changed':False}
paths={}
pid=int(prop('MainPID') or '0')
allowed={'--datadir','--configdir','--cachedir','--logdir','--ffmpeg','--ffmpeg-path','--webdir'}
try:
 a=pathlib.Path('/proc/'+str(pid)+'/cmdline').read_bytes().decode(errors='replace').split(chr(0))
 for i,v in enumerate(a):
  if v in allowed and i+1<len(a) and a[i+1].startswith('/'):paths[v]=a[i+1]
  elif '=' in v and v.split('=',1)[0] in allowed and v.split('=',1)[1].startswith('/'):paths[v.split('=',1)[0]]=v.split('=',1)[1]
except OSError:pass
r['runtime_path_flags']=paths
r['unit_working_directory']=prop('WorkingDirectory')
prefix=[]
if user and os.geteuid()!=pwd.getpwnam(user).pw_uid:prefix=['sudo','-n','-u',user,'--']
r['encoding_xml']=[]
candidates=list(dict.fromkeys([root/'config'/'encoding.xml',root/'data'/'config'/'encoding.xml',root/'data'/'encoding.xml',pathlib.Path(paths.get('--configdir',str(root/'config')))/'encoding.xml']))
for p in candidates:
 item={'path':str(p)}
 try: raw=p.read_text()
 except FileNotFoundError:continue
 except PermissionError:
  a=run(prefix+['cat',str(p)]) if prefix else None
  if a and a.returncode==0:raw=a.stdout
  else:
   item['read']='not_authorized';r['encoding_xml'].append(item);continue
 except OSError:continue
 try:
  e=ET.fromstring(raw)
  item['fields']={x.tag.split('}')[-1]:x.text for x in e.iter() if x.tag.split('}')[-1] in ('EncoderAppPath','EncoderAppPathDisplay','FFmpegPath','TranscodingTempPath','EnableHardwareEncoding','HardwareAccelerationType','EncodingThreadCount')}
  item['read']='ok';r['encoding_xml'].append(item)
 except ET.ParseError:item['read']='invalid_xml';r['encoding_xml'].append(item)
j=run(['journalctl','-u',svc,'-n','2000','--no-pager','-o','cat'],12)
if j:
 l=j.stdout.splitlines()
 r['journal_read_exit']=j.returncode
 r['ffmpeg_mentions']=sum('ffmpeg' in s.lower() for s in l)
 r['observed_ffmpeg_paths']=sorted(set(re.findall(r'/(?:usr|srv|opt)/[A-Za-z0-9_./-]+/ffmpeg(?=[\s"\x27,:;]|$)',j.stdout)))[:8]
 r['observed_ffmpeg_versions']=sorted(set(re.findall(r'ffmpeg version [0-9][A-Za-z0-9.+~-]*',j.stdout,re.I)))[:8]
 r['encoder_error_count']=sum(bool(re.search(r'(ffmpeg|encoder).{0,100}(not found|failed|invalid|permission denied|does not exist)',s,re.I)) for s in l)
if user:
 a=run(prefix+['/usr/bin/ffmpeg','-hide_banner','-nostdin','-loglevel','error','-f','lavfi','-i','testsrc2=size=320x180:rate=25','-f','lavfi','-i','sine=frequency=650:sample_rate=48000','-t','2','-c:v','libx264','-threads','1','-c:a','aac','-f','null','-'],15)
 r['service_identity_encode_exit']=a.returncode if a else None
 r['service_identity_test_pass']=bool(a and a.returncode==0)
 r['service_identity_permission_denied']=bool(a and ('password is required' in a.stderr.lower() or 'not allowed' in a.stderr.lower() or 'permission denied' in a.stderr.lower()))
print(json.dumps(r),flush=True)
